def semver_sort(versions):
    def parse(v):
        main = v
        # strip build metadata
        if '+' in main:
            main = main.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        if pre is not None:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            has_pre_flag = 0
        else:
            pre_key = []
            has_pre_flag = 1
        return (major, minor, patch, has_pre_flag, pre_key)

    return sorted(versions, key=parse)

